<?php
require_once __DIR__.'/../config/app.php';require_admin();$start=$_GET['start']??date('Y-m-01');$end=$_GET['end']??date('Y-m-d');$payment=$_GET['payment']??'';$where=['DATE(o.created_at) BETWEEN ? AND ?'];$params=[$start,$end];if(in_array($payment,['unpaid','waiting_verification','paid','rejected','refunded'],true)){$where[]='o.payment_status=?';$params[]=$payment;}$whereSql=implode(' AND ',$where);$stmt=db()->prepare("SELECT o.*,u.name FROM orders o JOIN users u ON u.id=o.user_id WHERE $whereSql ORDER BY o.created_at DESC");$stmt->execute($params);$orders=$stmt->fetchAll();
if(($_GET['export']??'')==='csv'){header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="laporan-eko-ceper-'.$start.'-'.$end.'.csv"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['Nomor Pesanan','Tanggal','Pembeli','Metode','Status Pembayaran','Status Pesanan','Total'],';');foreach($orders as $row)fputcsv($out,[$row['order_number'],$row['created_at'],$row['name'],strtoupper($row['payment_method']),payment_status_label($row['payment_status']),order_status_label($row['order_status']),$row['total_amount']],';');fclose($out);exit;}
$summary=db()->prepare("SELECT COUNT(*) total_orders,SUM(payment_status='paid') paid_orders,COALESCE(SUM(CASE WHEN payment_status='paid' THEN total_amount ELSE 0 END),0) revenue FROM orders o WHERE $whereSql");$summary->execute($params);$summary=$summary->fetch();$sold=db()->prepare("SELECT COALESCE(SUM(oi.quantity),0) FROM order_items oi JOIN orders o ON o.id=oi.order_id WHERE $whereSql AND o.payment_status='paid'");$sold->execute($params);$sold=(int)$sold->fetchColumn();$top=db()->prepare("SELECT oi.product_name,SUM(oi.quantity) qty,SUM(oi.subtotal) amount FROM order_items oi JOIN orders o ON o.id=oi.order_id WHERE $whereSql AND o.payment_status='paid' GROUP BY oi.product_name ORDER BY qty DESC LIMIT 10");$top->execute($params);$top=$top->fetchAll();$method=db()->prepare("SELECT payment_method,COUNT(*) total,COALESCE(SUM(CASE WHEN payment_status='paid' THEN total_amount ELSE 0 END),0) revenue FROM orders o WHERE $whereSql GROUP BY payment_method");$method->execute($params);$method=$method->fetchAll();$pageTitle='Laporan Penjualan';require APP_ROOT.'/includes/admin-header.php';
?>
<div class="admin-card mb-4 no-print"><div class="admin-card-body"><form class="row g-2 align-items-end"><div class="col-md-3"><label class="form-label">Tanggal mulai</label><input class="form-control" type="date" name="start" value="<?= e($start) ?>" required></div><div class="col-md-3"><label class="form-label">Tanggal akhir</label><input class="form-control" type="date" name="end" value="<?= e($end) ?>" required></div><div class="col-md-3"><label class="form-label">Status pembayaran</label><select class="form-select" name="payment"><option value="">Semua</option><?php foreach(['paid','unpaid','waiting_verification','rejected','refunded'] as $s):?><option value="<?= $s ?>" <?= $payment===$s?'selected':'' ?>><?= payment_status_label($s) ?></option><?php endforeach;?></select></div><div class="col-md-3 d-flex gap-2"><button class="btn btn-primary flex-grow-1">Tampilkan</button><a class="btn btn-success" href="?<?= e(query_string(['export'=>'csv'])) ?>"><i class="bi bi-file-earmark-spreadsheet"></i></a><button type="button" class="btn btn-light" onclick="window.print()"><i class="bi bi-printer"></i></button></div></form></div></div><div class="row g-3 mb-4"><?php $cards=[['Total Pesanan',$summary['total_orders']],['Transaksi Lunas',$summary['paid_orders']],['Produk Terjual',$sold],['Omzet Diterima',rupiah($summary['revenue'])]];foreach($cards as [$label,$value]):?><div class="col-6 col-xl-3"><div class="stat-card"><div class="text-muted small"><?= $label ?></div><div class="stat-value mt-1"><?= $value ?></div></div></div><?php endforeach;?></div><div class="row g-4 mb-4"><div class="col-lg-7"><div class="admin-card"><div class="admin-card-header"><strong>Transaksi <?= e($start) ?> s.d. <?= e($end) ?></strong></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Pesanan</th><th>Pembeli</th><th>Metode</th><th>Status</th><th>Total</th></tr></thead><tbody><?php foreach($orders as $row):?><tr><td><?= e($row['order_number']) ?><div class="small text-muted"><?= date('d/m/Y',strtotime($row['created_at'])) ?></div></td><td><?= e($row['name']) ?></td><td><?= strtoupper($row['payment_method']) ?></td><td><?= payment_status_label($row['payment_status']) ?></td><td><?= rupiah($row['total_amount']) ?></td></tr><?php endforeach;?></tbody></table></div></div></div><div class="col-lg-5"><div class="admin-card mb-4"><div class="admin-card-header"><strong>Produk terlaris (transaksi lunas)</strong></div><div class="admin-card-body"><?php foreach($top as $i=>$row):?><div class="d-flex justify-content-between py-2 border-bottom"><span><strong class="me-2"><?= $i+1 ?>.</strong><?= e($row['product_name']) ?></span><span class="badge bg-success-subtle text-success"><?= $row['qty'] ?> item</span></div><?php endforeach;?></div></div><div class="admin-card"><div class="admin-card-header"><strong>Rekap metode</strong></div><div class="admin-card-body"><?php foreach($method as $row):?><div class="d-flex justify-content-between py-2"><span><?= strtoupper($row['payment_method']) ?> (<?= $row['total'] ?>)</span><strong><?= rupiah($row['revenue']) ?></strong></div><?php endforeach;?></div></div></div></div>
<?php require APP_ROOT.'/includes/admin-footer.php';?>
